   331  /* count the number of args in pipeline definition */
   332  static size_t argc_params (paralist *params) {
   333      size_t argc = 0;
   334      for (; params != 0; params = params->next)
   335          argc++;
   336      return ++argc;  /* one extra for the sentinel */
   337  }
   338
   339  /* Sentinel for argument list */
   340  static char argv_sentinel[] = "step";
   341
   342  /* turn paralist into argc/argv style argument list */
   343  static char **argv_params (paralist *params, size_t argc) {
   344      char **argv;
   345      size_t i = 0;
   346      argv = pj_calloc (argc, sizeof (char *));
   347      if (0==argv)
   348          return 0;
   349      for (; params != 0; params = params->next)
   350          argv[i++] = params->param;
   351      argv[i++] = argv_sentinel;
   352      return argv;
   353  }
